import java.util.List;
import java.util.function.Function;

public class MethodReferenceDemo {
    public static void main(String[] args) {
        List<String> names = List.of("alice", "bob", "charlie");

        names.stream()
             .map(name -> name.toUpperCase())
             .forEach(result -> System.out.println(result));

        names.stream()
             .map(String::toUpperCase)
             .forEach(System.out::println);

        Function<String, Integer> lambda = s -> s.length();
        Function<String, Integer> reference = String::length;
        System.out.println(lambda.apply("test"));
        System.out.println(reference.apply("test"));
    }
}
```

The paired forms have the same functional result in this example. Their bytecode and runtime cost are implementation details, so the code makes no performance claim.

