import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

record Employee(String name, String department, int salary) {}

public class ComparatorDemo {
    public static void main(String[] args) {
        var employees = List.of(
            new Employee("Alice", "Engineering", 85_000),
            new Employee("Bob", "Engineering", 90_000),
            new Employee("Charlie", "Sales", 75_000)
        );

        var bySalaryDescending = employees.stream()
            .sorted(Comparator.comparingInt(Employee::salary).reversed())
            .toList();

        var byDepartmentThenSalary = employees.stream()
            .sorted(Comparator.comparing(Employee::department)
                .thenComparing(Comparator.comparingInt(Employee::salary).reversed()))
            .toList();

        // Arrays.asList permits a null element; List.of does not.
        var names = Arrays.asList("Alice", null, "Bob");
        names.sort(Comparator.nullsLast(Comparator.naturalOrder()));

        // This handles a null key returned by Employee::name.
        Comparator<Employee> byNullableName = Comparator.comparing(
            Employee::name, Comparator.nullsLast(Comparator.naturalOrder()));
    }
}
