import java.util.List;
import java.util.function.*;

public class MethodReferenceTypes {
    public static void main(String[] args) {
        // Type 1: Static method reference - ClassName::staticMethod
        BinaryOperator<Integer> maxFinder = Math::max;
        System.out.println(maxFinder.apply(5, 10));  // 10

        // Type 2: Bound instance method reference - object::instanceMethod
        String prefix = "Hello";
        Predicate<String> startsWithHello = prefix::startsWith;  // prefix is captured
        System.out.println(startsWithHello.test("Hel"));  // true

        // Type 3: Unbound instance method reference - ClassName::instanceMethod
        var names = List.of("alice", "bob", "charlie");
        names.stream()
             .map(String::toUpperCase)  // each element becomes the receiver
             .forEach(System.out::println);

        // Type 4: Constructor reference - ClassName::new
        Supplier<List<String>> listFactory = java.util.ArrayList::new;
        List<String> newList = listFactory.get();

        Function<Integer, List<String>> sizedListFactory = java.util.ArrayList::new;
        List<String> capacityList = sizedListFactory.apply(100);  // initial capacity
    }
}

import java.util.*;
import java.util.function.*;
import java.util.stream.Collectors;

record User(String username, String email) {
    // Constructor overloads for demonstration
    public User(String username) {
        this(username, username + "@example.com");
    }
}

public class ConstructorReferenceDemo {
    public static void main(String[] args) {
        // No-arg constructor reference with Supplier
        Supplier<List<String>> listFactory = ArrayList::new;
        List<String> list1 = listFactory.get();

        // Single-arg constructor reference with Function
        Function<String, User> userFactory = User::new;  // calls User(String)
        User alice = userFactory.apply("alice");

        // Two-arg constructor with BiFunction
        BiFunction<String, String, User> fullUserFactory = User::new;
        User bob = fullUserFactory.apply("bob", "bob@company.com");

        // Practical use: custom collection type in Stream.collect()
        var names = List.of("charlie", "alice", "bob", "alice");
        Set<String> uniqueSorted = names.stream()
            .collect(Collectors.toCollection(TreeSet::new));  // TreeSet maintains sorted order

        // Array constructor reference
        String[] array = names.stream().toArray(String[]::new);
    }
}
